## A reusable WASM library

This file is the **library half** of a two-example demo. Save it in the
playground as a local module named `mylinalg`, then run the companion
example ("Using a WASM Library") which imports from it.

The exports below are real `wasm function` declarations — top-level
WebAssembly kernels with explicit parameters and SIMD f32x4 bodies.
Each is compiled to wasm bytecode at transpile time and exported as a
regular JS function that the consumer can call.

**Note:** TJS ships a fuller version of these (and more) in
`tjs-lang/linalg`. This example mirrors the source so you can read
exactly what a wasm library looks like.
#/

/**
 * Dot product of two f32 vectors of length `n`.
 * Returns the sum of element-wise products as f64.
 * `n` must be a multiple of 4 (the SIMD lane width).
 */
export wasm function dot(a: Float32Array, b: Float32Array, n: i32): f64 {
  let acc = f32x4_splat(0.0)
  for (let i = 0; i < n; i += 4) {
    let off = i * 4
    let av = f32x4_load(a, off)
    let bv = f32x4_load(b, off)
    acc = f32x4_add(acc, f32x4_mul(av, bv))
  }
  return f32x4_extract_lane(acc, 0)
    + f32x4_extract_lane(acc, 1)
    + f32x4_extract_lane(acc, 2)
    + f32x4_extract_lane(acc, 3)
}

/**
 * Sum-of-squares of an f32 vector of length `n`.
 * For the L2 norm, take `Math.sqrt(norm_sq(a, n))` on the JS side.
 * Returning the squared value saves a sqrt; cosine similarity divides
 * by `sqrt(norm_sq(a) * norm_sq(b))`, which is one sqrt instead of two.
 */
export wasm function norm_sq(a: Float32Array, n: i32): f64 {
  let acc = f32x4_splat(0.0)
  for (let i = 0; i < n; i += 4) {
    let off = i * 4
    let av = f32x4_load(a, off)
    acc = f32x4_add(acc, f32x4_mul(av, av))
  }
  return f32x4_extract_lane(acc, 0)
    + f32x4_extract_lane(acc, 1)
    + f32x4_extract_lane(acc, 2)
    + f32x4_extract_lane(acc, 3)
}

// Sanity check before saving as a module
const a = wasmBuffer(Float32Array, 8)
const b = wasmBuffer(Float32Array, 8)
for (let i = 0; i < 8; i++) {
  a[i] = i + 1 // [1, 2, 3, 4, 5, 6, 7, 8]
  b[i] = i + 1
}

// dot([1..8], [1..8]) = 1 + 4 + 9 + 16 + 25 + 36 + 49 + 64 = 204
console.log('dot:', dot(a, b, 8))

// norm_sq([1..8]) = same as dot([1..8], [1..8]) = 204
console.log('norm_sq:', norm_sq(a, 8))

console.log('\nLooks good! Save this as `mylinalg` and run the consumer example next.')

function sum(numbers: number[]): number {
  return numbers.reduce((a, b) => a + b, 0)
}

function average(numbers: number[]): number {
  if (numbers.length === 0) return 0
  return sum(numbers) / numbers.length
}

function filterPositive(numbers: number[]): number[] {
  return numbers.filter((n) => n > 0)
}

const data = [-1, 2, -3, 4, 5, -6, 7]
console.log('Sum:', sum(data))
console.log('Average:', average(data))
console.log('Positive only:', filterPositive(data))

// JSON.parse returns `any`, so TypeScript accepts this as number[].
// One element is a string.
const scores: number[] = JSON.parse('[1, "2", 3]')
// stringify so the quotes show: the result is a string
console.log('Sum of scores:', JSON.stringify(sum(scores)))
console.log('Average of scores:', average(scores))

// Generic functions: TJS keeps what a value can show.
// An unconstrained type parameter loses its type, and the converter marks
// each one with a "TS types degraded" comment in the TJS it writes.

function identity<T>(value: T): T {
  return value
}

function first<T>(items: T[]): T | undefined {
  return items[0]
}

function wrap<T>(value: T): { value: T } {
  return { value }
}

// These work at runtime
console.log('identity(42):', identity(42))
console.log('identity("hello"):', identity('hello'))
console.log('first([1,2,3]):', first([1, 2, 3]))
console.log('wrap({ x: 1 }):', wrap({ x: 1 }))

/*#
`greet` builds a greeting from a name. TJS reads this block as
markdown documentation for the file.
*/

// By default TJS converts TypeScript the way tsc does: the types are
// erased. This line asks it to keep them as runtime checks:
/* @tjs TjsStrict */

/*test 'greet builds a greeting' {
  expect(greet('ts')).toBe('Hello, ts!')
}*/

function greet(name: string): string {
  return `Hello, ${name}!`
}

// A correct call works as usual
console.log(greet('World'))

// Compiled by tsc, this prints "Hello, 42!".
// Under TJS, greet returns an error value instead of a greeting.
// `bad` is typed `any` because the error has fields `string` lacks.
const bad: any = greet(42 as any)
console.log('Bad call result:', bad)

console.log('is an error:', bad instanceof Error)
console.log('path:', bad.path)
console.log('expected:', bad.expected, 'actual:', bad.actual)

function calculate({ a = 10, b = 5 }) {
  let sum = a + b
  let product = a * b
  let power = a ** b
  let sqrt = Math.sqrt(a)
  let max = Math.max(a, b)
  let rounded = Math.floor(a / b)
  return { sum, product, power, sqrt, max, rounded }
}

/* @tjs TjsStrict */

// In a real module: import { isMonadicError } from 'tjs-lang/runtime'
declare function isMonadicError(
  value: unknown
): value is Error & { path: string; expected?: string; actual?: string }

function divide(a: number, b: number): number {
  if (b === 0) return NaN
  return a / b
}

function half(n: number): number {
  console.log('half ran') // skipped when given an error
  return n / 2
}

// Valid calls work normally
console.log('10 / 2 =', divide(10, 2))
console.log('10 / 0 =', divide(10, 0))

// A bad argument is rejected: divide returns an error instead of running.
// tsc types the result as number, so widen it to say what can come back.
const result: number | Error = divide('ten' as any, 2)
console.log('divide("ten", 2) =', result)

if (isMonadicError(result)) {
  console.log('message:', result.message)
  console.log('path:', result.path)
  console.log('expected:', result.expected, 'actual:', result.actual)
}

// Skip the check, and the next checked function hands the error back
const halved = half(result as number)
console.log('halved is result:', halved === result)

// Operators and templates do not check: the error turns into text
console.log(`template: ${result}`)
console.log('plus one:', (result as number) + 1)

