// --- Scalar math ---

function addNumbers(! a: 0, b: 0):! 0 {
  return wasm {
    return a + b
  }
}

function factorial(! n: 0):! 0 {
  return wasm {
    let result = 1.0          // f64: an i32 here would overflow at 13!
    for (let i = 2; i <= n; i++) {
      result = result * i
    }
    return result
  }
}

function lerp(! a: 0.0, b: 0.0, t: 0.0):! 0.0 {
  return wasm {
    return a + (b - a) * t
  }
}

// --- Array processing ---

function sumArray(! arr: Float32Array, len: 0):! 0.0 {
  return wasm {
    let sum = 0.0
    for (let i = 0; i < len; i++) {
      sum = sum + arr[i]
    }
    return sum
  }
}

